import Link from "next/link";
import { notFound } from "next/navigation";
import ServiceCards from "@/components/ServiceCards";
import serviceAreas from "@/data/serviceAreas.json";
import RoavioLayout from "@/layout/RoavioLayout";

export default async function CityToursPage({ params }) {
  const { city } = await params;
  const area = serviceAreas.find((entry) => entry.city === city);

  if (!area) notFound();

  const cards = area.services.map((tour) => ({
    name: tour.name,
    image: tour.image || area.image,
    description: tour.summary || tour.description,
    duration: tour.duration,
    href: `/service-areas/${area.city}/${tour.slug}`,
  }));

  return (
    <RoavioLayout>
      <section className="tour-grid-section section-padding">
        <div className="container">
          <Link href="/service-areas">All Tour Services</Link>

          <h1 className="mt-3">{area.name}</h1>
          <p className="mb-4">{area.description}</p>

          {cards.length > 0 ? (
            <ServiceCards cards={cards} />
          ) : (
            <p>Tour options will be added soon.</p>
          )}
        </div>
      </section>
    </RoavioLayout>
  );
}